# Generated by Selenium IDE
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC


class TestUserManagement:
    def setup_method(self, method):
        self.driver = webdriver.Chrome()
        self.driver.maximize_window()
        self.wait = WebDriverWait(self.driver, 10)

    def teardown_method(self, method):
        self.driver.quit()

    def test_user_management(self):
        # Authenticate as Port Administrator
        self.driver.get("https://portide.vercel.app/login")
        self.wait.until(EC.visibility_of_element_located((By.NAME, "email"))).send_keys("aleena302005@gmail.com")
        self.wait.until(EC.visibility_of_element_located((By.NAME, "password"))).send_keys("Aleena@2005")
        self.wait.until(EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))).click()

        # Navigate to Admin User Management view
        self.wait.until(EC.url_contains("/admin"))
        self.driver.get("https://portide.vercel.app/admin/users")

        # Wait for user directory table to render
        user_table = self.wait.until(
            EC.presence_of_element_located((By.CSS_SELECTOR, "table, .user-directory-container"))
        )
        assert user_table.is_displayed()

        # Click Add User button to open modal dialog
        add_user_btn = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'Add User') or contains(., 'Create User')]"))
        )
        add_user_btn.click()

        # Verify user creation modal is displayed
        modal = self.wait.until(EC.visibility_of_element_located((By.CSS_SELECTOR, "[role='dialog'], .modal-container")))
        assert modal.is_displayed()
        time.sleep(2)
